//! Runtime support for code generated by the imping modding suite.
//!
//! Generated bindings depend on this crate and nothing else. It provides:
//!
//! - [`Module`]: a module's expected identity. [`Module::init`] finds the
//!   module in the running process and checks it is the build the bindings
//!   were generated from, then resolves addresses relative to its base.
//! - [`Global`]: a typed global variable at an address in a module.
//! - [`Hook`]: the guard returned by a generated function's `hook`, which
//!   enables, disables and (on drop) disables the hook.
//! - [`Error`]: everything that can go wrong.
//!
//! [`Module`] and [`Global`] are also usable on their own, without generated
//! code.
//!
//! # Example
//!
//! ```no_run
//! use imping_runtime::{Global, Module};
//!
//! static GAME: Module = Module::new("game.exe", 0x64b8f2a1, 0xa2b000);
//! static GRAVITY: Global<f32> = Global::new(&GAME, 0x3a1200);
//!
//! fn main() -> imping_runtime::Result<()> {
//!     // SAFETY: `game.exe` with this timestamp and image size keeps an `f32`
//!     // at RVA 0x3a1200.
//!     unsafe { GAME.init() }?;
//!     // SAFETY: `init` succeeded, so the pointer is the game's global.
//!     unsafe { *GRAVITY.ptr() = 4.9 };
//!     Ok(())
//! }
//! ```
//!
//! # Unloading
//!
//! Hooks jump into code in the mod that installed them. Before a mod's DLL is
//! unloaded, drop (or disable) every [`Hook`] it holds. A hook kept with
//! [`Hook::leak`] means the mod must never be unloaded.
//!
//! # Platforms
//!
//! Windows only for now. On other platforms the crate compiles, but
//! [`Module::init`] returns [`Error::UnsupportedPlatform`].

mod backend;
mod error;
mod global;
mod hook;
mod module;
mod sys;

pub use crate::error::{Error, Result};
pub use crate::global::Global;
pub use crate::hook::Hook;
pub use crate::module::Module;

/// Plumbing for code generated by `imping-codegen`. Not a supported API: it
/// changes in step with the generator.
#[doc(hidden)]
pub mod __private {
    pub use crate::hook::{Slot, install};
}
